/**
 * Compute the length of the common prefix of the first `aLength` chars of `a`
 * and the first `bLength` chars of `b`.
 */
function commonPrefixLength(
  a: string,
  aLength: number,
  b: string,
  bLength: number
): number {
  let i: number;

  for (i = 0; i < aLength && i < bLength; i++) {
    const aCharCode = a.charCodeAt(i);
    const bCharCode = b.charCodeAt(i);

    if (aCharCode !== bCharCode) {
      break;
    }
  }

  return i;
}

